      {
        id: 'u01-hs4',
        pinNumber: 4,
        position: [0.0, 1.8, 0.0],
        color: '#38bdf8',
        badgeLabel: "Termometre",
        title: { tr: "Destilasyon Başlığı ve Termometre", en: "Distillation Head & Thermometer", de: "Destillieraufsatz und Thermometer", fr: "Tête de distillation et thermomètre", ru: "Перегонная насадка и термометр", ar: "رأس التقطير ومقياس الحرارة", zh: "蒸馏头与温度计", ku: "Serê Distîlasyonê û Termometre" },
        description: { tr: "Termometrenin cıva haznesi, soğutucuya giden yan borunun tam hizasına yerleştirilir. Böylece yoğunlaşan buharın gerçek sıcaklığı ölçülür.", en: "The thermometer bulb is aligned precisely level with the condenser side-arm outlet to measure the exact condensation temperature of the entering vapor fraction.", de: "Das Thermometergefäß sitzt genau auf Höhe des Seitenabzweigs zum Kühler, um die wahre Temperatur des übergehenden Dampfes zu erfassen.", fr: "Le réservoir du thermomètre doit être placé exactement au niveau du bras latéral pour mesurer fidèlement la température des vapeurs qui distillent.", ru: "Ртутный шарик термометра располагают точно на уровне бокового отвода к холодильнику. Так измеряется истинная температура конденсирующегося пара.", ar: "يوضع مستودع مقياس الحرارة بمحاذاة فتحة الأنبوب الجانبي المؤدي للمكثف لقياس درجة حرارة البخار المتكثف بدقة.", zh: "温度计的水银球应与通向冷凝管的支管口处于同一高度，这样测得的是正在冷凝的蒸气的实际温度。", ku: "Hezîneya cîwayê ya termometreyê tam li asta lûleya alî ya ku diçe sarkerê tê danîn. Bi vî awayî germahiya rastîn a buhara ku şile dibe tê pîvan." },
        examFact: { tr: "ÖSYM İpucu: Termometre sıvı içine daldırılmaz. Sıvının sıcaklığı kaynama noktasından yüksek (aşırı ısınmış) olabilir; saf maddenin kaynama noktası buhar fazında ölçülür.", en: "Exam Tip: The thermometer must never touch the boiling liquid. Liquid can be superheated; the true boiling point must be measured in the equilibrium vapor stream.", de: "Prüfungstipp: Das Thermometer darf niemals in die Flüssigkeit tauchen. Die Flüssigkeit kann überhitzt sein; der wahre Siedepunkt wird im Dampf gemessen.", fr: "Conseil d'examen: Le thermomètre ne doit pas tremper dans le liquide. Le liquide peut être surchauffé; le point d'ébullition se mesure dans la vapeur.", ru: "Совет: термометр не погружают в жидкость. Жидкость может быть перегрета выше температуры кипения; температуру кипения чистого вещества измеряют в паровой фазе.", ar: "ملاحظة للامتحان: لا يُغمر مقياس الحرارة في السائل؛ فقد تكون حرارة السائل أعلى من درجة غليانه (فرط التسخين)، وتُقاس درجة غليان المادة النقية في الطور البخاري.", zh: "应试提示：温度计不能插入液体中。液体的温度可能高于沸点（过热）；纯物质的沸点应在气相中测量。", ku: "Serişteya ÖSYM-ê: Termometre naxe nav şileyê. Germahiya şileyê dikare ji xala kelînê bilindtir be (zêde germbûyî); xala kelînê ya madeya paqij di buharê de tê pîvan." },
        name: { tr: "Destilasyon Başlığı ve Termometre", en: "Distillation Head & Thermometer", de: "Destillieraufsatz und Thermometer", fr: "Tête de distillation et thermomètre", ru: "Перегонная насадка и термометр", ar: "رأس التقطير ومقياس الحرارة", zh: "蒸馏头与温度计", ku: "Serê Distîlasyonê û Termometre" },
        role: { tr: "Destilasyon Başlığı ve Termometre", en: "Distillation Head & Thermometer", de: "Destillieraufsatz und Thermometer", fr: "Tête de distillation et thermomètre", ru: "Перегонная насадка и термометр", ar: "رأس التقطير ومقياس الحرارة", zh: "蒸馏头与温度计", ku: "Serê Distîlasyonê û Termometre" },
        quickHint: { tr: "Destilasyon Başlığı ve Termometre", en: "Distillation Head & Thermometer", de: "Destillieraufsatz und Thermometer", fr: "Tête de distillation et thermomètre", ru: "Перегонная насадка и термометр", ar: "رأس التقطير ومقياس الحرارة", zh: "蒸馏头与温度计", ku: "Serê Distîlasyonê û Termometre" },
        osymExamFact: { tr: "ÖSYM İpucu: Termometre sıvı içine daldırılmaz. Sıvının sıcaklığı kaynama noktasından yüksek (aşırı ısınmış) olabilir; saf maddenin kaynama noktası buhar fazında ölçülür.", en: "Exam Tip: The thermometer must never touch the boiling liquid. Liquid can be superheated; the true boiling point must be measured in the equilibrium vapor stream.", de: "Prüfungstipp: Das Thermometer darf niemals in die Flüssigkeit tauchen. Die Flüssigkeit kann überhitzt sein; der wahre Siedepunkt wird im Dampf gemessen.", fr: "Conseil d'examen: Le thermomètre ne doit pas tremper dans le liquide. Le liquide peut être surchauffé; le point d'ébullition se mesure dans la vapeur.", ru: "Совет: термометр не погружают в жидкость. Жидкость может быть перегрета выше температуры кипения; температуру кипения чистого вещества измеряют в паровой фазе.", ar: "ملاحظة للامتحان: لا يُغمر مقياس الحرارة في السائل؛ فقد تكون حرارة السائل أعلى من درجة غليانه (فرط التسخين)، وتُقاس درجة غليان المادة النقية في الطور البخاري.", zh: "应试提示：温度计不能插入液体中。液体的温度可能高于沸点（过热）；纯物质的沸点应在气相中测量。", ku: "Serişteya ÖSYM-ê: Termometre naxe nav şileyê. Germahiya şileyê dikare ji xala kelînê bilindtir be (zêde germbûyî); xala kelînê ya madeya paqij di buharê de tê pîvan." },
      }
