    title: { tr: "NaCl İyonik Kristal Örgüsü (FCC)", en: "NaCl Face-Centered Cubic Crystal Lattice", de: "NaCl-Ionengitter (Flächenzentriert-kubisch)", fr: "Réseau cristallin ionique de NaCl (CFC)", ru: "Ионная кристаллическая решётка NaCl (ГЦК)", ar: "الشبكة البلورية الأيونية لكلوريد الصوديوم NaCl (FCC)", zh: "NaCl离子晶体晶格（面心立方）", ku: "Tora Krîstala Îyonîk a NaCl (FCC)" },
    subtitle: { tr: "Yüzey Merkezli Kübik Birim Hücre ve 6:6 Koordinasyon Küresi", en: "FCC Unit Cell and 6:6 Octahedral Coordination Spheres", de: "Flächenzentrierte Elementarzelle und 6:6-Koordinationssphäre", fr: "Maille cubique à faces centrées et coordination octaédrique 6:6", ru: "Гранецентрированная кубическая элементарная ячейка и координация 6:6", ar: "خلية وحدة مكعبة متمركزة الأوجه وكرة التناسق 6:6", zh: "面心立方晶胞与6:6配位", ku: "Şaneya Yekîneyî ya Kubîk a Rû-Navendî û Qada Koordînasyonê ya 6:6" },
    description: { tr: "Yüzey Merkezli Kübik Birim Hücre ve 6:6 Koordinasyon Küresi", en: "FCC Unit Cell and 6:6 Octahedral Coordination Spheres", de: "Flächenzentrierte Elementarzelle und 6:6-Koordinationssphäre", fr: "Maille cubique à faces centrées et coordination octaédrique 6:6", ru: "Гранецентрированная кубическая элементарная ячейка и координация 6:6", ar: "خلية وحدة مكعبة متمركزة الأوجه وكرة التناسق 6:6", zh: "面心立方晶胞与6:6配位", ku: "Şaneya Yekîneyî ya Kubîk a Rû-Navendî û Qada Koordînasyonê ya 6:6" },
