    title: { tr: "İyon-Dipol Hidratlaşma Kabuğu (Na⁺ ve Cl⁻)", en: "Ion-Dipole Hydration Shell (Na⁺ & Cl⁻ Solvation Spheres)", de: "Ion-Dipol-Hydratationshülle (Na⁺ und Cl⁻)", fr: "Sphères d'hydratation ion-dipôle (Na⁺ et Cl⁻)", ru: "Ион-дипольная гидратная оболочка (Na⁺ и Cl⁻)", ar: "غلاف الإماهة أيون-ثنائي قطب (Na⁺ وCl⁻)", zh: "离子-偶极水合层(Na⁺ 与Cl⁻)", ku: "Qalikê Hîdratasyonê yê Îyon-Dîpol (Na⁺ û Cl⁻)" },
    subtitle: { tr: "Su Dipollerinin Zıt Kutuplarla İyonları Kuşatması ve Çözünme Entalpisi", en: "Water Dipoles Orienting Around Ions & Hydration Enthalpy", de: "Ausrichtung von Wasserdipolen um Ionen und Hydratationsenthalpie", fr: "Orientation des dipôles d'eau autour des ions et enthalpie d'hydratation", ru: "Окружение ионов противоположными полюсами диполей воды и энтальпия растворения", ar: "توجه ثنائيات قطب الماء حول الأيونات وحرارة الذوبان", zh: "水分子偶极以相反的一端包围离子；溶解焓", ku: "Dorpêçkirina Îyonan ji aliyê Polên Dijber ên Dîpolên Avê ve û Entalpiya Helbûnê" },
    description: { tr: "Su Dipollerinin Zıt Kutuplarla İyonları Kuşatması ve Çözünme Entalpisi", en: "Water Dipoles Orienting Around Ions & Hydration Enthalpy", de: "Ausrichtung von Wasserdipolen um Ionen und Hydratationsenthalpie", fr: "Orientation des dipôles d'eau autour des ions et enthalpie d'hydratation", ru: "Окружение ионов противоположными полюсами диполей воды и энтальпия растворения", ar: "توجه ثنائيات قطب الماء حول الأيونات وحرارة الذوبان", zh: "水分子偶极以相反的一端包围离子；溶解焓", ku: "Dorpêçkirina Îyonan ji aliyê Polên Dijber ên Dîpolên Avê ve û Entalpiya Helbûnê" },
    category: 'gas_solution',
