/**
 * Master catalog of 3D chemistry scenes containing the 32 primary scenes
 * and legacy alias entries for backwards-compatibility with test suites.
 */
export const THREE_SCENES_DATA: ChemicalSceneSpec[] = [
  ...PRIMARY_32_SCENES,
  ...LEGACY_CONTRACT_SCENES,
];

/**
 * Looks up a scene by canonical ID or alias.
 */
export function getSceneById(id: string): ChemicalSceneSpec | undefined {
  return (
    PRIMARY_32_SCENES.find((s) => s.id === id) ||
    PRIMARY_32_SCENES.find((s) => s.aliases?.includes(id)) ||
    PRIMARY_32_SCENES.find((s) => s.unitId === id) ||
    LEGACY_CONTRACT_SCENES.find((s) => s.id === id)
  );
}
